use kobo_web_document::{Limits,SupplyBudget,SnapshotState,HistoryState,InputState,FocusState,TargetState};
fn snap()->SnapshotState{SnapshotState{history:None,input:None,focus:None,target:None}}
fn run(c:&str,b:&str,l:&Limits,s:&SnapshotState)->kobo_web_document::style_tree::StyleTree{let h=format!("<!doctype html><style>{c}</style>{b}");kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],l,None,SupplyBudget::CANONICAL,s)}
#[test] fn original11_public_neutral_color_real_article_div_all_combinations(){
 let html=include_str!("fixtures/has_typed_pair_oracle.html");let ids=["anchor","post","story","head","thumb","headwide","thumbwide","headsquare","thumbsquare","credit","video"];
 let baseline=run("",html,&Limits::DEFAULT,&snap());assert!(!baseline.unsupported&&!baseline.truncated,"baseline unsupported={} truncated={} first={:?} input={} dom={} retained={} attrs={} decls={}",baseline.unsupported,baseline.truncated,baseline.diagnostics.first_reason(),baseline.diagnostics.input_bytes,baseline.diagnostics.dom_nodes,baseline.diagnostics.retained_nodes,baseline.diagnostics.dropped_attributes,baseline.diagnostics.expanded_declarations);
 for(qi,q)in include_str!("fixtures/has_typed_pair_original11.txt").lines().enumerate(){let t=run(&format!("{q}{{color:red}}"),html,&Limits::DEFAULT,&snap());assert!(!t.unsupported&&!t.truncated,"{q}");for name in ["none","a","b","both","wrongtype","case","classcase","substring","nbsp","space","excluded","self","outside"]{let key=format!("{name}-{}",ids[qi]);let text=t.nodes.iter().find(|n|n.text.as_deref().is_some_and(|v|v.starts_with(&key))).unwrap();let n=&t.nodes[text.parent.unwrap()];let yes=matches!(name,"a"|"b"|"both"|"case"|"space");assert_eq!(n.style.color,if yes{0xff0000}else{0},"{key} {q}");}println!("TYPED-HAS ORIGINAL {} realtags originalsubject neutralCOLOR selectoronly unwrappedmedia complete",qi+1);}
}
#[test] fn browser_rank_colors_max_equal_sourceorder_id_single_sum_and_not(){let t=run("",include_str!("fixtures/has_typed_pair_cascade.html"),&Limits::DEFAULT,&snap());assert!(!t.unsupported&&!t.truncated);for(k,w)in[("e",0xff0000),("strong",0xff0000),("w",0x0000ff),("s",0xff0000),("m",0x0000ff)]{assert_eq!({let text=t.nodes.iter().find(|n|n.text.as_deref().is_some_and(|v|v.starts_with(k))).unwrap();t.nodes[text.parent.unwrap()].style.color},w,"{k}");}}
#[test] fn global_work_attrpartial_limits_state_and_default_unchanged(){let q="div:has(article.x,div.y){color:red}";let b=format!("<div>{}</div>","<article class=z></article>".repeat(50));assert!(!run(q,&b,&Limits::DEFAULT,&snap()).truncated);let t=run(&q.repeat(100),&b.repeat(200),&Limits{max_input_bytes:4_000_000,max_nodes:200_000,..Limits::DEFAULT},&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);
 let b=format!("<div><article {} class=x></article></div>",(0..40).map(|i|format!("data-x{i}=a ")).collect::<String>());let t=run(q,&b,&Limits::DEFAULT,&snap());assert!(t.truncated&&t.diagnostics.dropped_attributes>0);assert!(!t.unsupported);
 for l in [Limits{max_input_bytes:30,..Limits::DEFAULT},Limits{max_nodes:1,..Limits::DEFAULT},Limits{max_text_bytes:0,..Limits::DEFAULT}]{let t=run(q,"<div><article>text</article></div>",&l,&snap());assert!(t.truncated||t.unsupported);}
 let q=".absent:has(article.a,div.b):where(:not(:focus)){color:red}";let mut s=snap();assert!(run(q,"<div></div>",&Limits::DEFAULT,&s).unsupported);s.history=Some(HistoryState::FreshNoHistory);s.input=Some(InputState::QuiescentCapture);assert!(run(q,"<div></div>",&Limits::DEFAULT,&s).unsupported);s.focus=Some(FocusState::UnfocusedInitial);assert!(!run(q,"<div></div>",&Limits::DEFAULT,&s).unsupported);assert!(run(q,"<div autofocus></div>",&Limits::DEFAULT,&s).unsupported);s.target=Some(TargetState::Fragment("x".into()));assert!(!run("div:has(article.a,div.b):target{color:red}","<div id=x><article class=a></article></div>",&Limits::DEFAULT,&s).unsupported);
 assert!(kobo_web_document::parse_style_tree(b"<!doctype html><style>div:has(article.a,div.b){color:red}</style><div><article class=a></article></div>",&[],&Limits::DEFAULT).unsupported);
}
#[test] fn mixed_pair_commas_sixteen_seventeen_othercommas(){for(n,w)in[(16,false),(17,true)]{let qs=vec![":has(article.a,div.b):not(.x,.y)";n].join(",");let t=run(&format!("{qs}{{color:red}}"),"<div><article class=a></article></div>",&Limits::DEFAULT,&snap());assert_eq!(t.unsupported,w);}for q in [r#":has(article.a,div.b)[data-x="a,b"]"#,":not(article.a,div.b)",":has(article.a,.b)",":has(.a,div.b)",":has(article.a,div.b,p.c)"]{assert!(run(&format!("{q}{{color:red}}"),"<div><article class=a></article></div>",&Limits::DEFAULT,&snap()).unsupported);}}
